 i:[[2,"stk","auberginer, i skiver"],[600,"g","hakket lam eller oksekød"],[1,"stk","løg, hakket"],[2,"fed","hvidløg"],[1,"dåse","hakkede tomater"],[2,"spsk","tomatpure"],[1,"tsk","kanel"],[1,"tsk","oregano"],[50,"g","smør"],[50,"g","hvedemel"],[5,"dl","mælk"],[1,"stk","æg"],[75,"g","revet parmesan"],[null,"","olivenolie, salt og peber"]],
